	@Override
	public List<PersoDTO> importPersosAndSave(String user) throws IOException, FileImportException {
		logger.info("Import started at {}", LocalDateTime.now());
		logger.info("working {}", working);
		if (!working) {
			working = true;
			List<FileMetadata> filesMeta = fileService.getAllUnimportedFiles();

			if (filesMeta != null && !filesMeta.isEmpty()) {
				logger.info("Usao je u importPersosAndSave i ima elemenata : {}", filesMeta.size());
			} else {
				logger.info("Usao je u importPersosAndSave: lista je prazna ili null");
			}

			List<Perso> persosList = new ArrayList<>();

			for (FileMetadata metaChecker : filesMeta) {
				if (persoRepo.checkExistFiles(metaChecker.getFileName()) != 0) {
					logger.info("Duplicate File, File {} is already imported", metaChecker.getFileName());
					working = false;
					throw new IllegalArgumentException("The file " + metaChecker.getFileName() + " already used. Remove the specified file from the location or rename it.");
				}

			}

			for (FileMetadata meta : filesMeta) {

				logger.info("***********************BEGIN IMPORT SIA : {} ***********************", meta.getFileName());
				int numberOfRowInFile = 0;
				try (BufferedReader reader = new BufferedReader(new FileReader(meta.getFile()))) {
					String line;
					while ((line = reader.readLine()) != null) {
						logger.debug("Processing line: {}", line);
						Perso p = fileRowToObject(line, meta.getFile().getName(), meta.getCreatedAt());
						if (p != null) {
							persoRepo.save(p);
							persosList.add(p);
							numberOfRowInFile++;
							logger.debug("Saved Perso: {}", p);
						} else {
							logger.warn("Skipped invalid line: {}", line);
						}
//					Perso p = persoRepo.save(fileRowToObject(line, meta.getFile().getName(), meta.getCreatedAt()));
//					persosList.add(p);
//					numberOfRowInFile++;
					}
					logger.info("Saved filename: {}, with number of line: {}", meta.getFileName(), numberOfRowInFile);
				} catch (Exception e) {
					working = false;
					logger.error(e.getLocalizedMessage());
				}

				int numberOfRowInDB = persoRepo.numberOfRowByFilenameInPersoTbl(meta.getFileName(), statusPreImported);
				logger.info("Filename: {}, number of row in DB: {}", meta.getFileName(), numberOfRowInDB);

				if (numberOfRowInDB == numberOfRowInFile) {

					logger.info("The number of lines and rows are the same.");
					String toArchive = fileService.createArchiveStructureIfNotExist();
					fileService.moveFileToArchive(toArchive, meta.getFileName());

				} else {
					logger.error("The number of lines and rows are NOT the same.");
					persosList.removeIf(t -> t.getFileImportName().equals(meta.getFileName()));
					persoRepo.deleteByImportDateAndFilename(meta.getFileName(), statusPreImported);

				}

				logger.info("Insert logging after import.");
				if (!persosList.isEmpty()) {
					persoHistoryService.saveLog(persosList.get(0), persosList.get(0).getFileImportTime(), persosList.get(0).getODatum(), user, "importFiles");
				} else {
					logger.warn("persosList is empty. Cannot save log.");
				}

//			persoHistoryService.saveLog(persosList.get(0), persosList.get(0).getFileImportTime(),persosList.get(0).getODatum(), user, "importFiles"); numberOfRowInFile = 0;
				persosList.clear();
				logger.info("***********************END IMPORT SIA : {} *****************************", meta.getFileName());

			}

			logger.info("Send email after IMPORT!");
			mailService.sendEMailPersoByStatus(statusImported, "1");
			logger.info("Perso list size {}" ,  persosList.size());
			working = false;
			logger.info("Import end at {}", LocalDateTime.now());
			logger.info("working {}", working);
			return persoMapper.entityToDtoList(persosList);
		}
		logger.info("Preskocio poziv i vratio praznu listu: {}", LocalDateTime.now());
		List<Perso> persosListEmpty = new ArrayList<>();
		return persoMapper.entityToDtoList(persosListEmpty);
	}
	

