			// CARD
			sia.setCardNumber(line.substring(104, 120).trim());
			sia.setCardFirstFour(line.substring(104, 108).trim());
			sia.setCardLastFour(line.substring(22, 26).trim());
			sia.setCardValidFrom(line.substring(27, 32).trim());
			sia.setCardValidUntil(line.substring(33, 38));
			sia.setCardCvc(line.substring(93, 101).trim());
			sia.setCardEmboss1(line.substring(39, 65).trim());
			sia.setCardEmboss2(line.substring(66, 92).trim());
			// DELIVERY
			sia.setDeliveryTo(line.substring(250, 285).trim());
			sia.setDeliveryToClient(line.substring(286, 321).trim());
			sia.setDeliveryAddress2(line.substring(322, 357).trim());
			sia.setDeliveryStreet(line.substring(358, 398).trim());
			sia.setDeliveryCity(line.substring(399, 434).trim());
			sia.setDeliveryPostcode(line.substring(435, 445).trim());
			sia.setDeliveryCountry(line.substring(446, 481).trim());
			// BRANCH
			sia.setBranchImport(line.substring(482, 487));
			// FILE
			sia.setFileImportName(fileName);
			sia.setFileImportTime(currentDateAndTime);
			sia.setStatus(statusService.getStatusByStatus(statusPreImported).getStatus());
			sia.setUpdatedBy("SYSTEM"); // STATUS
			sia.setUpdatedAt(currentDateAndTime); // STATUS
			// META
			sia.setEan(line.substring(488, 488 + 8) + String.format("%05d", ThreadLocalRandom.current().nextInt(100_000)));
			sia.setBatchid(batchID);
			sia.setType(String.valueOf(fileName.charAt(4)));
			sia.setDeliverymethode(fileName.substring(9, 11));
			sia.setPackagedef(fileName.substring(12, 15));
