			/*
			 * long primaryAccountNumber = Long.parseLong(sia.getCardNumber());
			 * CardDestination cdo = cds.getBranchWithProcedure(primaryAccountNumber);
			 * sia.setBranchExport(cdo.getDestinationBranch());
			 * sia.setCardTypeName(cdo.getCardTypeName());
			 * sia.setClientNumber(cdo.getClientNumber());
			 */
			break;

		case "P":
			sia.setCardNumber(line.substring(7, 23));
			sia.setSearchCode(line.substring(0, 6).trim());
			sia.setPinBlock(line.substring(30, 46).trim());
			sia.setCardValidUntil(line.substring(28, 30) + "/" + line.substring(26, 28));
			sia.setCardEmboss1(line.substring(99, 125).trim());
