			sia.setDeliveryToClient(line.substring(99, 134).trim());
			sia.setDeliveryAddress2("");
			sia.setDeliveryStreet(line.substring(169, 204).trim());
			sia.setDeliveryCity(line.substring(204, 239).trim());
			sia.setDeliveryPostcode(line.substring(239, 249).trim());
			sia.setDeliveryCountry(line.substring(249, 284).trim());
