	@Override
	public List<Perso> getAllByTypeAndStatus(String type, String status) {
		List<Perso> cardsOrpins = persoRepo.findAllByTypeAndStatusEver(type, status);

		return cardsOrpins.stream()
				.peek(this::maskedCardNumber)
				.sorted(Comparator
						.comparing(Perso::getUpdatedAt, Comparator.nullsLast(Comparator.naturalOrder())).reversed()
						.thenComparing(Perso::getFileExportTime, Comparator.nullsLast(Comparator.naturalOrder())).reversed()
						.thenComparing(Perso::getOBranch, Comparator.nullsLast(Comparator.naturalOrder())).reversed()
				)
				.collect(Collectors.toList());
	}

