		logger.info("Pocetak procedure SP_GET_RM_EMAIL!!!");

		StoredProcedureQuery query = entityManager.createStoredProcedureQuery("SP_GET_RM_EMAIL", String.class);

		query.registerStoredProcedureParameter("p_rm_user", String.class, ParameterMode.IN);
