package rs.unicredit.cardlifecycle.service.impl;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.List;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import jakarta.persistence.EntityManager;
import jakarta.persistence.ParameterMode;
import jakarta.persistence.StoredProcedureQuery;
import rs.unicredit.cardlifecycle.model.CardDestination;
import rs.unicredit.cardlifecycle.model.Perso;
import rs.unicredit.cardlifecycle.repository.PersoRepository;
import rs.unicredit.cardlifecycle.service.CardDestinationService;
import rs.unicredit.cardlifecycle.service.MailService;

@Service
public class CardDestinationServiceImpl implements CardDestinationService {
	private static final Logger logger = LoggerFactory.getLogger(CardDestinationServiceImpl.class);

	@Value("${customs.links.rpt}")
	private String rpt;

	@Autowired
	private EntityManager entityManager;


	@Autowired
	private PersoRepository persoRepository;

	@Autowired
	MailService mailService;

	@Override
	public CardDestination getBranchWithProcedure(Long primaryAccountNumber) {
		logger.info("Pocetak procedure getBranchWithProcedure!!!");
	   StoredProcedureQuery query = entityManager.createStoredProcedureQuery("SP_GET_BRANCH", CardDestination.class);
	   query.registerStoredProcedureParameter("p_trpano", Long.class, ParameterMode.IN);
	   query.registerStoredProcedureParameter("p_primary_account_number", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_card_type_code", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_card_type_name", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_destination_branch", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_account_number", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_client_number", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_emboss2", String.class, ParameterMode.OUT);
	   query.registerStoredProcedureParameter("p_result", void.class, ParameterMode.REF_CURSOR);
	   query.setParameter("p_trpano", primaryAccountNumber);
	   List<CardDestination> cardDestinations;
	   boolean execute = query.execute();
	   cardDestinations = query.getResultList();

		return cardDestinations.get(0) ;

	}
