package rs.unicredit.cardlifecycle.service.impl;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.net.MalformedURLException;
import java.util.Arrays;
import jakarta.persistence.EntityManager;
import jakarta.persistence.ParameterMode;
import jakarta.persistence.StoredProcedureQuery;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import org.springframework.boot.test.context.SpringBootTest;
import rs.unicredit.cardlifecycle.model.CardDestination;
import rs.unicredit.cardlifecycle.model.Perso;
import rs.unicredit.cardlifecycle.repository.PersoRepository;
import rs.unicredit.cardlifecycle.service.MailService;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CardDestinationServiceImplTest {

    @Mock
    private EntityManager entityManager;

    @Mock
    private StoredProcedureQuery storedProcedureQuery;

    @Mock
    private PersoRepository persoRepository;

    @Mock
    private MailService mailService;

    @InjectMocks
    private CardDestinationServiceImpl cardDestinationService;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    void testGetBranchWithProcedure() {
        // Arrange
        Long primaryAccountNumber = 123456789L;
        CardDestination cardDestination = new CardDestination();
        when(entityManager.createStoredProcedureQuery("SP_GET_BRANCH", CardDestination.class))
                .thenReturn(storedProcedureQuery);
        when(storedProcedureQuery.registerStoredProcedureParameter(anyString(), any(), any())).thenReturn(storedProcedureQuery);
        when(storedProcedureQuery.setParameter("p_trpano", primaryAccountNumber)).thenReturn(storedProcedureQuery);
        when(storedProcedureQuery.execute()).thenReturn(true);
        when(storedProcedureQuery.getResultList()).thenReturn(Arrays.asList(cardDestination));

        // Act
        CardDestination result = cardDestinationService.getBranchWithProcedure(primaryAccountNumber);

        // Assert
        assertNotNull(result);
        verify(entityManager, times(1)).createStoredProcedureQuery("SP_GET_BRANCH", CardDestination.class);
        verify(storedProcedureQuery, times(1)).setParameter("p_trpano", primaryAccountNumber);
        verify(storedProcedureQuery, times(1)).execute();
    }


    @Test
    void testUpdateExportBranch_Success() {
        // Arrange
        when(entityManager.createStoredProcedureQuery("SP_SET_BRANCH_OPT", CardDestination.class))
