@RestController
@RequestMapping("/api/cib")
@Tag(name = "CibController", description = "API for CIB operations")
public class CibController {

	@Autowired
	CibService cibService;

	@Autowired
	CardRegistrationHistoryService cardHistory;

	@Autowired
	ShipmentMapper shipmentMapper;

	@Autowired
	LoggingService logger;

	@Autowired
	private JwtUtils jwtUtils;

	@Operation(summary = "Fetch all CIB shipments for branch")
	@GetMapping("/get-all-cib-shipment")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<List<ShipmentDTO>> getAllShipmentForCib(HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all CIB shipment for my branch");
		String department = jwtUtils.getCibDepartment();
		/*
		Ovaj department menjam dovlacenjem iz getDepartmentFromJwtTokenCIB
		 */
		List<ShipmentDTO> shipmentList = shipmentMapper
				.persoToShipmentDtoList(cibService.getAllShipmentForMyCib(department));
		return ResponseEntity.ok(shipmentList);
	}
	@Operation(summary = "Fetch all CIB shipments for branch")
	@GetMapping("/get-all-cib-shipment-returned")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<List<ShipmentExDTO>> getAllShipmentForCibReturn(HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all CIB shipment returned for my branch");
		String department = jwtUtils.getCibDepartment();
		List<ShipmentExDTO> shipmentList = shipmentMapper
				.persoExToShipmentDtoList(cibService.getAllShipmentForMyCibReturned(department));
		return ResponseEntity.ok(shipmentList);
	}

	@Operation(summary = "Fetch all received cards  for CIB")
	@GetMapping("/get-all-cib-received")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<List<ShipmentDTO>> getAllReceived(HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all received shipment for my branch");
		String department = jwtUtils.getCibDepartment();
		List<ShipmentDTO> shipmentList = shipmentMapper
				.persoToShipmentDtoList(cibService.getAllReceivedCardsCib(department));
		return ResponseEntity.ok(shipmentList);
	}
	
	@Operation(summary = "Fetch all defict cards  for CIB")
	@GetMapping("/get-all-cib-activated")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<List<ShipmentDTO>> getAllActivated(HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all deficit CARDS for my branch");
		String department = jwtUtils.getCibDepartment();
		List<ShipmentDTO> shipmentList = shipmentMapper
				.persoToShipmentDtoList(cibService.getAllActivatedCardsCib(department));
		return ResponseEntity.ok(shipmentList);
	}
	
	@Operation(summary = "Fetch all received cards  for CIB")
	@GetMapping("/get-all-cib-deficit")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<List<ShipmentDTO>> getAllDeficit(HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all received shipment for my branch");
		String department = jwtUtils.getCibDepartment();
		List<ShipmentDTO> shipmentList = shipmentMapper
				.persoToShipmentDtoList(cibService.getAllDeficitCardsCib(department));
		return ResponseEntity.ok(shipmentList);
	}
	
	@Operation(summary = "", description = "Method reserved for CIB workers with ROLE_CIB and accept all shipment for my CIB")
	@PostMapping("/accept-all-cib-shipment")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<Boolean> acceptAllCibShipment(@RequestBody List<ShipmentDTO> shipmentDto,
			HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all shipment for my branch");
		String userName = jwtUtils.getUsername();
		String branch = jwtUtils.getCibDepartment();
		return ResponseEntity.ok(cibService.acceptAllCibShipment(shipmentDto, userName, branch));
	}

	@Operation(summary = "", description = "Method reserved for branch workers with ROLE_BRANCH and accept one per one shipemnt for my branch")
	@PostMapping("/accept-cib-shipment")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<Boolean> acceptShipment(@RequestBody ShipmentDTO shipmentDto, HttpServletRequest request) {
		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE,
				"Accept shipment to: " + shipmentDto.getOBranch());
		String userName = jwtUtils.getUsername();
		String branch = jwtUtils.getCibDepartment();
		return ResponseEntity.ok(cibService.acceptShipmentCib(shipmentDto, userName, branch));
	}
	@Operation(summary = "")
	@PostMapping("/returnToUnReceived-all-cards")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
