		logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Fetch all shipment for my branch");
		String userName = jwtUtils.getUsername();
		String branch = jwtUtils.getCibDepartment();
		return ResponseEntity.ok(cibService.returnToUnReceivedAllCibShipment(shipmentDto, userName, branch));
	}
	@Operation(summary = "")
	@PostMapping("/returnToUnReceived-card")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','CIB')")
	public ResponseEntity<Boolean> returnToUnReceivedShipment(@RequestBody ShipmentDTO shipmentDto, HttpServletRequest request) {
		try {
			logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Return to UNRECEIVED/SENT for card: " + shipmentDto.getCardNumber());
			logger.info(request, OperationCategory.DATA_READ_MODIFY_DELETE, "Return to unreceived card");

			String department = jwtUtils.getCibDepartment();
			String userName = jwtUtils.getUsername();
			return ResponseEntity.ok(cibService.returnToUnReceivedCibShipment(shipmentDto, userName, department));
		} catch (CardActivationException e) {
			throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage(), e);
		}
	}
