package rs.unicredit.cardlifecycle.service.impl;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.test.util.ReflectionTestUtils;
import rs.unicredit.cardlifecycle.CS;
import rs.unicredit.cardlifecycle.model.Perso;
import rs.unicredit.cardlifecycle.service.PersoHistoryService;
import rs.unicredit.cardlifecycle.repository.PersoRepository;

import java.time.LocalDateTime;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class PersoServiceImplTest {

    @Mock
    private PersoRepository persoRepo;

    @Mock
    private PersoHistoryService persoHistoryService;

    @InjectMocks
    private PersoServiceImpl service;

    @BeforeEach
    void setup() {
        ReflectionTestUtils.setField(service, "status_Otp_opened", "opened");
    }

    @Test
    void testFillPxCodeOtpremniceUpdatesPxAndSaves() {
        Perso perso = new Perso();
        perso.setODatum(LocalDateTime.MIN);

        when(persoRepo.findByOBranchAndOStatusOrderByOBranchAsc("BR1", "opened"))
                .thenReturn(List.of(perso));

        service.fillPxCodeOtpremnice("BR1", "PX123", "user1");

        assertEquals("PX123", perso.getOPxcode());
        verify(persoRepo, times(1)).save(perso);
        verify(persoHistoryService, times(1)).saveLog(eq(perso), any(), any(), eq("user1"), eq("UpdatePXCode"));
    }

    @Test
    void testMaskedCardNumberMasksWhenLengthValid() {
        Perso perso = new Perso();
        perso.setCardNumber("1111222233334444");

        service.maskedCardNumber(perso);

        assertEquals("1111 **** **** 4444", perso.getCardNumber());
    }

    @Test
    void testMaskedCardNumberNoChangeWhenInvalidLength() {
        Perso perso = new Perso();
        perso.setCardNumber("123");

        service.maskedCardNumber(perso);

        assertEquals("123", perso.getCardNumber());
    }

    @Test
    void testFillOtpremniceSetsOtpDataAndSaves() {
        ReflectionTestUtils.setField(service, "statusExported", "1");

        Perso exported = new Perso();
        exported.setPackagedef("000");
        exported.setDeliverymethode("br");
        exported.setBranchExport("BR1");
        exported.setEan("EAN1");
        exported.setStatus("1");
        exported.setODatum(null);

        when(persoRepo.findByfileImportNameAndStatus("file.dat", "1")).thenReturn(List.of(exported));

        List<Perso> result = service.fillOtpremnice("file.dat", "user1");

        assertEquals(1, result.size());
        Perso updated = result.get(0);
        assertEquals("Redovna", updated.getOPaket());
        assertEquals("BR1", updated.getOBranch());
        assertEquals("opened", updated.getOStatus());
        assertEquals(CS.NOT_PRINTED.getId(), updated.getOStampa());
        verify(persoRepo).save(exported);
        verify(persoHistoryService).saveLog(eq(exported), any(), any(), eq("user1"), eq("SendToProduction"));
    }

    @Test
    void testVracanjeOtpremniceUpdatesStatusesAndSaves() {
        ReflectionTestUtils.setField(service, "statusReturn", CS.REJECT.getId());
        ReflectionTestUtils.setField(service, "status_Otp_opened", "opened");

        Perso exPerso = new Perso();
        exPerso.setDeliverymethode("ex");
        exPerso.setPackagedef("000");
        exPerso.setOBranch("BRX");
        exPerso.setBranchExport("BEX");

        Perso brPerso = new Perso();
        brPerso.setDeliverymethode("br");
        brPerso.setPackagedef("001");
        brPerso.setOBranch("XXXX");
        brPerso.setBranchExport("BR1");

        when(persoRepo.findByOPxcode("ean1")).thenReturn(List.of(exPerso, brPerso));

        List<Perso> result = service.vracanjeOtpremnice("ean1", "user1");

        assertEquals(2, result.size());
        assertEquals(CS.REJECT.getId(), exPerso.getStatus());
        assertEquals(CS.REJECT.getId(), brPerso.getStatus());
        assertEquals("opened", brPerso.getOStatus());
        assertEquals(CS.PRINTED_RETURNED.getId(), brPerso.getOStampa());
        verify(persoRepo, atLeastOnce()).save(any(Perso.class));
        verify(persoHistoryService).saveLog(eq(exPerso), any(), any(), eq("user1"), eq("VracanjeOtpremnice"));
    }
}
